pub(crate) fn decode(payload:&store::io::IoPayload,control:&mut SqliteSnapshotControl<'_>)->Result<SemioPresentationSnapshot,ValueError>{
 let limits=control.limits();crate::standards::v1::subsets::presentation::io::sqlite::snapshot::admit_layout(limits)?;
 let size=match payload{store::io::IoPayload::Binary(value)=>value.len(),store::io::IoPayload::Text(value)=>value.len()};if size>limits.max_file_bytes{return Err(ValueError::new(ValueRefusalKind::OwnershipLimit,"Semio Presentation native input exceeds file limit"))}
 control.allocation_stage(store::sqlite_snapshot::SqliteSnapshotPhase::DecodeNative,|remaining,checkpoint|{
  let mut callback=|event:semio_framework_value::native_decoding::NativeDecodeProgress|checkpoint(event.completed,event.total);let mut native_control=NativeDecodeControl::new(remaining,&mut callback);
  let result=(||->Result<SemioPresentationSnapshot,ValueError>{let result=match payload{
   store::io::IoPayload::Binary(value)=>{let body=store::semio_format::unwrap_binary_controlled(value,STDIO_SEMIOPRESENTATION_DOCUMENT_SCHEMA,store::semio_format::Component::Pack,1,&mut native_control).map_err(store::semio_format::SemioError::into_value_error)?;binary(body,&mut native_control,limits)?},
   store::io::IoPayload::Text(value)=>{let body=store::semio_format::split_text_preamble_controlled(value,STDIO_SEMIOPRESENTATION_DOCUMENT_SCHEMA,store::semio_format::Component::Dsl,1,&mut native_control).map_err(store::semio_format::SemioError::into_value_error)?;document(body,&mut native_control,limits)?}
  };let result=native::Owned::new(result);native_control.checkpoint()?;Ok(result.take())})();(result,native_control.owned_bytes())
 })?
}
fn f64(reader:&mut store::ByteReader<'_>)->Result<f64,ValueError>{reader.read_f64_le().map_err(|error|ValueError::new(ValueRefusalKind::InvalidValue,error.to_string()))}
fn frame_binary(reader:&mut store::ByteReader<'_>)->Result<SlideFrame,ValueError>{Ok(SlideFrame{origin:SemioPoint2{x:f64(reader)?,y:f64(reader)?},width:f64(reader)?,height:f64(reader)?})}
fn option(reader:&mut store::ByteReader<'_>,control:&mut NativeDecodeControl<'_>)->Result<Option<String>,ValueError>{match reader.read_u8().map_err(|error|ValueError::new(ValueRefusalKind::InvalidValue,error.to_string()))?{0=>Ok(None),1=>native::text(reader,control).map(Some),_=>Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid Presentation native optional presence"))}}
fn placeholder_binary(reader:&mut store::ByteReader<'_>,control:&mut NativeDecodeControl<'_>)->Result<PlaceholderKind,ValueError>{Ok(match reader.read_u8().map_err(|error|ValueError::new(ValueRefusalKind::InvalidValue,error.to_string()))?{0=>PlaceholderKind::Title,1=>PlaceholderKind::Subtitle,2=>PlaceholderKind::Body,3=>PlaceholderKind::Footer,4=>PlaceholderKind::SlideNumber,5=>PlaceholderKind::DateTime,6=>PlaceholderKind::Other{value:native::text(reader,control)?},_=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid Presentation native placeholder"))})}
fn blocks_binary(reader:&mut store::ByteReader<'_>,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits,entities:&mut usize)->Result<Vec<DocBlock>,ValueError>{native::entities(entities,1,limits)?;native::binary_list(reader,control,limits,entities,|reader,control,entities|{let body=control.borrow_text(native::bytes(reader)?)?;document_native::block_text(body,control,limits,entities)})}
fn shape_binary(reader:&mut store::ByteReader<'_>,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits,entities:&mut usize)->Result<SlideShape,ValueError>{native::entities(entities,1,limits)?;let tag=reader.read_u8().map_err(|error|ValueError::new(ValueRefusalKind::InvalidValue,error.to_string()))?;let frame=frame_binary(reader)?;Ok(match tag{
0=>SlideShape::TextBox{frame,blocks:blocks_binary(reader,control,limits,entities)?},1=>{let asset_id=native::text(reader,control)?;let mut image=native::Owned::new(SlidePictureImage{asset_id,mime:String::new(),bytes:Vec::new()});image.get_mut().mime=native::text(reader,control)?;image.get_mut().bytes=control.copy_bytes(native::bytes(reader)?)?;SlideShape::Picture{frame,image:image.take()}},
2=>{let rows=native::binary_list(reader,control,limits,entities,|reader,control,entities|{let cells=native::binary_list(reader,control,limits,entities,|reader,control,entities|Ok(SlideTableCell{blocks:blocks_binary(reader,control,limits,entities)?}))?;Ok(SlideTableRow{cells})})?;SlideShape::Table{frame,rows}},3=>SlideShape::Placeholder{frame,kind:placeholder_binary(reader,control)?},_=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid Presentation native shape"))})}
fn shapes_binary(reader:&mut store::ByteReader<'_>,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits,entities:&mut usize)->Result<Vec<SlideShape>,ValueError>{native::binary_list(reader,control,limits,entities,|reader,control,entities|shape_binary(reader,control,limits,entities))}
pub(crate) fn binary(body:&[u8],control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits)->Result<SemioPresentationSnapshot,ValueError>{crate::standards::v1::subsets::presentation::io::sqlite::snapshot::admit_binary(body,control,limits)?;let mut reader=store::ByteReader::new(body);if reader.read_u8().map_err(|error|ValueError::new(ValueRefusalKind::InvalidValue,error.to_string()))?!=1{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"unsupported Presentation native format"))}let mut entities=0;native::entities(&mut entities,1,limits)?;let schema=native::text(&mut reader,control)?;let mut owner=native::Owned::new(SemioPresentationSnapshot{schema,masters:Vec::new(),layouts:Vec::new(),slides:Vec::new()});
owner.get_mut().masters=native::binary_list(&mut reader,control,limits,&mut entities,|reader,control,entities|{let id=native::text(reader,control)?;let mut owner=native::Owned::new(SlideMaster{id,shapes:Vec::new()});owner.get_mut().shapes=shapes_binary(reader,control,limits,entities)?;Ok(owner.take())})?;
owner.get_mut().layouts=native::binary_list(&mut reader,control,limits,&mut entities,|reader,control,entities|{let id=native::text(reader,control)?;let mut owner=native::Owned::new(SlideLayout{id,master_id:String::new(),shapes:Vec::new()});owner.get_mut().master_id=native::text(reader,control)?;owner.get_mut().shapes=shapes_binary(reader,control,limits,entities)?;Ok(owner.take())})?;
owner.get_mut().slides=native::binary_list(&mut reader,control,limits,&mut entities,|reader,control,entities|{let id=native::text(reader,control)?;let mut owner=native::Owned::new(Slide{id,layout_id:None,shapes:Vec::new(),notes:Vec::new()});owner.get_mut().layout_id=option(reader,control)?;owner.get_mut().shapes=shapes_binary(reader,control,limits,entities)?;owner.get_mut().notes=blocks_binary(reader,control,limits,entities)?;Ok(owner.take())})?;if reader.remaining()!=0{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"Presentation native trailing bytes"))}Ok(owner.take())}
fn optional_text(value:&str,control:&mut NativeDecodeControl<'_>)->Result<Option<String>,ValueError>{if value=="[0]"{return Ok(None)}let[tag,value]=native::record(value,control)?;if tag!="1"{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid Presentation native optional presence"))}native::hex_text(value,control).map(Some)}
fn number_text(value:&str,control:&mut NativeDecodeControl<'_>)->Result<f64,ValueError>{control.scoped_stage(|control|{control.begin_stage(value.len())?;for _ in value.bytes(){control.step()?;}value.parse::<u64>().map(f64::from_bits).map_err(|_|ValueError::new(ValueRefusalKind::InvalidValue,"invalid Presentation native IEEE unsigned64 word"))})}
fn frame_text(value:&str,control:&mut NativeDecodeControl<'_>)->Result<SlideFrame,ValueError>{let[origin,width,height]=native::record(value,control)?;let[x,y]=native::record(origin,control)?;Ok(SlideFrame{origin:SemioPoint2{x:number_text(x,control)?,y:number_text(y,control)?},width:number_text(width,control)?,height:number_text(height,control)?})}
fn placeholder_text(value:&str,control:&mut NativeDecodeControl<'_>)->Result<PlaceholderKind,ValueError>{Ok(match value{"T"=>PlaceholderKind::Title,"S"=>PlaceholderKind::Subtitle,"B"=>PlaceholderKind::Body,"F"=>PlaceholderKind::Footer,"N"=>PlaceholderKind::SlideNumber,"D"=>PlaceholderKind::DateTime,_=>{let value=value.strip_prefix('O').ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,"invalid Presentation native placeholder"))?;let[value]=native::record(value,control)?;PlaceholderKind::Other{value:native::hex_text(value,control)?}}})}
fn shape_text(value:&str,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits,entities:&mut usize)->Result<SlideShape,ValueError>{native::entities(entities,1,limits)?;let(tag,value)=value.split_at_checked(1).ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,"Presentation native shape tag missing"))?;let[frame,value]=native::record(value,control)?;let frame=frame_text(frame,control)?;Ok(match tag{
"X"=>SlideShape::TextBox{frame,blocks:document_native::blocks_text(value,control,limits,entities)?},
"P"=>{let[asset_id,mime,bytes]=native::record(value,control)?;let asset_id=native::hex_text(asset_id,control)?;let mut image=native::Owned::new(SlidePictureImage{asset_id,mime:String::new(),bytes:Vec::new()});image.get_mut().mime=native::hex_text(mime,control)?;image.get_mut().bytes=native::hex(bytes,control)?;SlideShape::Picture{frame,image:image.take()}},
"T"=>{let rows=native::text_list(value,control,limits,entities,|value,control,entities|{let cells=native::text_list(value,control,limits,entities,|value,control,entities|Ok(SlideTableCell{blocks:document_native::blocks_text(value,control,limits,entities)?}))?;Ok(SlideTableRow{cells})})?;SlideShape::Table{frame,rows}},"H"=>SlideShape::Placeholder{frame,kind:placeholder_text(value,control)?},_=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid Presentation native shape"))})}
fn shapes_text(value:&str,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits,entities:&mut usize)->Result<Vec<SlideShape>,ValueError>{native::text_list(value,control,limits,entities,|value,control,entities|shape_text(value,control,limits,entities))}
pub(crate) fn document(body:&str,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits)->Result<SemioPresentationSnapshot,ValueError>{crate::standards::v1::subsets::presentation::io::sqlite::snapshot::admit_document(body,control,limits)?;let mut entities=0;native::entities(&mut entities,1,limits)?;let fields=native::fields(body,["schema","masters","layouts","slides"],control)?;let schema=fields[0].ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,"Presentation native schema missing"))?;let masters=fields[1].unwrap_or("[]");let layouts=fields[2].unwrap_or("[]");let slides=fields[3].unwrap_or("[]");let schema=native::hex_text(schema,control)?;let mut owner=native::Owned::new(SemioPresentationSnapshot{schema,masters:Vec::new(),layouts:Vec::new(),slides:Vec::new()});
owner.get_mut().masters=native::text_list(masters,control,limits,&mut entities,|value,control,entities|{let[id,shapes]=native::record(value,control)?;let id=native::hex_text(id,control)?;let mut owner=native::Owned::new(SlideMaster{id,shapes:Vec::new()});owner.get_mut().shapes=shapes_text(shapes,control,limits,entities)?;Ok(owner.take())})?;
owner.get_mut().layouts=native::text_list(layouts,control,limits,&mut entities,|value,control,entities|{let[id,master_id,shapes]=native::record(value,control)?;let id=native::hex_text(id,control)?;let mut owner=native::Owned::new(SlideLayout{id,master_id:String::new(),shapes:Vec::new()});owner.get_mut().master_id=native::hex_text(master_id,control)?;owner.get_mut().shapes=shapes_text(shapes,control,limits,entities)?;Ok(owner.take())})?;
owner.get_mut().slides=native::text_list(slides,control,limits,&mut entities,|value,control,entities|{let[id,layout_id,shapes,notes]=native::record(value,control)?;let id=native::hex_text(id,control)?;let mut owner=native::Owned::new(Slide{id,layout_id:None,shapes:Vec::new(),notes:Vec::new()});owner.get_mut().layout_id=optional_text(layout_id,control)?;owner.get_mut().shapes=shapes_text(shapes,control,limits,entities)?;owner.get_mut().notes=document_native::blocks_text(notes,control,limits,entities)?;Ok(owner.take())})?;Ok(owner.take())}
